["luaCode"] = "HA_CUSTOM_OPTIONS = {\n  -- Core pins\n  { key=\"pin_AH\",          label=\"Auction House\", default=true },\n  { key=\"pin_TradingPost\", label=\"Trading Post\", default=true },\n  { key=\"pin_CraftOrders\", label=\"Crafting Orders\", default=true },\n  { key=\"pin_Inn\",         label=\"Inn\", default=true },\n  { key=\"pin_Portal1\",     label=\"Portal (center)\", default=true },\n  { key=\"pin_Portal2\",     label=\"Portal (west)\", default=true },\n  { key=\"pin_Dummies\",     label=\"Training Dummies\", default=true },\n  { key=\"pin_Upgrade\",     label=\"Upgrade\", default=true },\n  { key=\"pin_Transmog\",    label=\"Transmog\", default=true },\n\n  -- Crafting (single toggle)\n  { key=\"pin_Crafting\",    label=\"Crafting\", default=true },\n\n  -- New\n  { key=\"pin_Catalyst\",    label=\"Catalyst\", default=true },\n}\n\n-- Silvermoon (Midnight) World Map Overlay (UiMapID 2393)\n-- No \"Groups\" and no \"Show All\": everything is controlled individually.\n-- Crafting is a single label controlled by one toggle (\"Crafting\").\n-- Idempotent: safe even if HenniAuras re-executes the CustomLua frequently.\n\nlocal TARGET_MAP_ID = 2393\nlocal opts = opts or {}\n\nlocal regionKey = tostring(region or \"NO_REGION\")\n\n_G.HA_CustomOverlayStates = _G.HA_CustomOverlayStates or {}\nlocal st = _G.HA_CustomOverlayStates[regionKey]\nif not st then\n  st = {\n    overlay = nil,\n    activePins = {},\n    pinPool = {},\n    hooked = false,\n    lastMapID = nil,\n    lastW = nil,\n    lastH = nil,\n    lastOptHash = nil,\n  }\n  _G.HA_CustomOverlayStates[regionKey] = st\nend\n\nlocal function GetCanvas()\n  if WorldMapFrame and WorldMapFrame.GetCanvas then\n    return WorldMapFrame:GetCanvas()\n  end\n  if WorldMapFrame and WorldMapFrame.ScrollContainer and WorldMapFrame.ScrollContainer.Child then\n    return WorldMapFrame.ScrollContainer.Child\n  end\n  return nil\nend\n\nlocal function ShouldShow()\n  if not (WorldMapFrame and WorldMapFrame.IsShown and WorldMapFrame:IsShown()) then return false end\n  if not WorldMapFrame.GetMapID then return false end\n  return WorldMapFrame:GetMapID() == TARGET_MAP_ID\nend\n\nlocal function Clamp01(v)\n  if type(v) ~= \"number\" then return 1 end\n  if v < 0 then return 0 end\n  if v > 1 then return 1 end\n  return v\nend\n\nlocal function GetDesiredAlpha()\n  -- HenniAuras applies the Display alpha slider to the CUSTOM_LUA region:\n  --   region:SetAlpha(...)\n  -- Our overlay is on the WorldMap canvas, so we must pull that alpha and apply it ourselves.\n  local a = 1\n  if region and region.GetAlpha then\n    local ra = region:GetAlpha()\n    if type(ra) == \"number\" then a = ra end\n  end\n  return Clamp01(a)\nend\n\nlocal function ClearPins()\n  for i = 1, #st.activePins do\n    local p = st.activePins[i]\n    if p then\n      p:Hide()\n      p:SetParent(nil)\n      st.pinPool[#st.pinPool + 1] = p\n    end\n  end\n  wipe(st.activePins)\nend\n\nlocal function AcquirePin(parent)\n  local p = tremove(st.pinPool)\n  if not p then\n    p = CreateFrame(\"Frame\", nil, parent)\n\n    -- Marker dot\n    p.dot = p:CreateTexture(nil, \"OVERLAY\")\n    p.dot:SetTexture(\"Interface\\\\BUTTONS\\\\WHITE8X8\")\n    p.dot:SetSize(24, 24)\n    -- Ensure the dot draws \"on top\" within its frame\n    if p.dot.SetDrawLayer then p.dot:SetDrawLayer(\"OVERLAY\", 7) end\n\n    -- Label text\n    p.text = p:CreateFontString(nil, \"OVERLAY\", \"GameFontNormal\")\n    p.text:SetJustifyH(\"LEFT\")\n    -- Ensure the label draws \"on top\" within its frame\n    if p.text.SetDrawLayer then p.text:SetDrawLayer(\"OVERLAY\", 7) end\n\n    -- Default anchor: dot at center, label to the right\n    p.dot:ClearAllPoints()\n    p.dot:SetPoint(\"CENTER\", p, \"CENTER\", 0, 0)\n    p.text:ClearAllPoints()\n    p.text:SetPoint(\"LEFT\", p.dot, \"RIGHT\", 8, 0)\n  end\n\n\nfunction ApplyLabelAnchor(pin, d)\n  -- Per-pin label anchoring relative to the dot.\n  -- Default = RIGHT with (8,0), matching the original behavior.\n  local anchor = (d and d.labelAnchor) or \"RIGHT\"\n  local ox = (d and d.labelOffsetX)\n  local oy = (d and d.labelOffsetY)\n\n  if not pin.text then return end\n\n  pin.text:ClearAllPoints()\n\n  if anchor == \"LEFT\" then\n    pin.text:SetJustifyH(\"RIGHT\")\n    pin.text:SetPoint(\"RIGHT\", pin.dot or pin, \"LEFT\", ox or -8, oy or 0)\n  elseif anchor == \"TOP\" then\n    pin.text:SetJustifyH(\"CENTER\")\n    pin.text:SetPoint(\"BOTTOM\", pin.dot or pin, \"TOP\", ox or 0, oy or 8)\n  elseif anchor == \"BOTTOM\" then\n    pin.text:SetJustifyH(\"CENTER\")\n    pin.text:SetPoint(\"TOP\", pin.dot or pin, \"BOTTOM\", ox or 0, oy or -8)\n  elseif anchor == \"TOPRIGHT\" then\n    pin.text:SetJustifyH(\"LEFT\")\n    pin.text:SetPoint(\"BOTTOMLEFT\", pin.dot or pin, \"TOPRIGHT\", ox or 8, oy or 8)\n  elseif anchor == \"TOPLEFT\" then\n    pin.text:SetJustifyH(\"RIGHT\")\n    pin.text:SetPoint(\"BOTTOMRIGHT\", pin.dot or pin, \"TOPLEFT\", ox or -8, oy or 8)\n  elseif anchor == \"BOTTOMRIGHT\" then\n    pin.text:SetJustifyH(\"LEFT\")\n    pin.text:SetPoint(\"TOPLEFT\", pin.dot or pin, \"BOTTOMRIGHT\", ox or 8, oy or -8)\n  elseif anchor == \"BOTTOMLEFT\" then\n    pin.text:SetJustifyH(\"RIGHT\")\n    pin.text:SetPoint(\"TOPRIGHT\", pin.dot or pin, \"BOTTOMLEFT\", ox or -8, oy or -8)\n  elseif anchor == \"CENTER\" then\n    pin.text:SetJustifyH(\"CENTER\")\n    pin.text:SetPoint(\"CENTER\", pin.dot or pin, \"CENTER\", ox or 0, oy or 0)\n  else\n    pin.text:SetJustifyH(\"LEFT\")\n    pin.text:SetPoint(\"LEFT\", pin.dot or pin, \"RIGHT\", ox or 8, oy or 0)\n  end\nend\n\n  p:SetParent(parent)\n\n  -- Keep pin frames on the same (high) strata/level as the overlay.\n  if parent and parent.GetFrameStrata and parent.GetFrameLevel then\n    local ps = parent:GetFrameStrata()\n    local pl = parent:GetFrameLevel()\n    if ps and p.SetFrameStrata then p:SetFrameStrata(ps) end\n    if pl and p.SetFrameLevel then p:SetFrameLevel(pl + 10) end\n  end\n\n  st.activePins[#st.activePins + 1] = p\n  return p\nend\n\nlocal function EnsureOverlay()\n  local canvas = GetCanvas()\n  if not canvas then return nil end\n\n  if not st.overlay or st.overlay:GetParent() ~= canvas then\n    if st.overlay then\n      st.overlay:SetParent(canvas)\n      st.overlay:ClearAllPoints()\n    else\n      st.overlay = CreateFrame(\"Frame\", nil, canvas)\n    end\n    st.overlay:SetAllPoints(canvas)\n\n    -- Raise overlay above most WorldMap elements (quest icons, POIs, etc.)\n    st.overlay:SetFrameStrata(\"TOOLTIP\")\n    st.overlay:SetFrameLevel(10000)\n\n    -- Don't block clicks/hover on the map\n    if st.overlay.EnableMouse then st.overlay:EnableMouse(false) end\n  end\n\n  -- Always apply the desired alpha (from HenniAuras display alpha slider)\n  if st.overlay and st.overlay.SetAlpha then\n    st.overlay:SetAlpha(GetDesiredAlpha())\n  end\n\n  return st.overlay\nend\n\nlocal function Enabled(key)\n  return opts[key] ~= false\nend\n\nlocal function GetPins()\n  local pins = {\n    -- Auction House\n    { x=0.50369096247355, y=0.74944536685944, text=\"Auction House\", size=60, color={1,1,1}, optKey=\"pin_AH\" , labelAnchor=\"TOP\", labelOffsetX=0, labelOffsetY=8 },\n    -- Trading Post\n    { x=0.49374532699585, y=0.78281783580780, text=\"Trading Post\", size=60, color={0,1,0}, optKey=\"pin_TradingPost\" , labelAnchor=\"TOP\", labelOffsetX=0, labelOffsetY=8 },\n    -- Crafting Orders\n    { x=0.4498, y=0.5585, text=\"Crafting Orders\", size=60, color={1,0,0}, optKey=\"pin_CraftOrders\" , labelAnchor=\"BOTTOM\", labelOffsetX=0, labelOffsetY=-4 },\n    -- Crafting\n    { x=0.47030613835653, y=0.53625894145966, text=\"Crafting\", size=50, color={0,0.8,1}, optKey=\"pin_Crafting\" , labelAnchor=\"RIGHT\", labelOffsetX=8, labelOffsetY=0 },\n    -- Catalyst\n    { x=0.4020, y=0.6556, text=\"Catalyst\", size=60, color={0,0.8,1}, optKey=\"pin_Catalyst\" , labelAnchor=\"LEFT\", labelOffsetX=-8, labelOffsetY=0 },\n    -- Inn\n    { x=0.55457598597209, y=0.70340460510254, text=\"Inn\", size=60, color={1,0.5,0}, optKey=\"pin_Inn\" , labelAnchor=\"RIGHT\", labelOffsetX=8, labelOffsetY=0 },\n    -- Portals\n    { x=0.53224145863851, y=0.66066983901978, text=\"Portal\", size=60, color={0,0.8,1}, optKey=\"pin_Portal1\" , labelAnchor=\"BOTTOM\", labelOffsetX=8, labelOffsetY=0 },\n    { x=0.3560,             y=0.6808,             text=\"Portal\", size=60, color={0,0.8,1}, optKey=\"pin_Portal2\" , labelAnchor=\"BOTTOM\", labelOffsetX=8, labelOffsetY=0 },\n    -- Training Dummies\n    { x=0.36368925857544, y=0.84993203163147, text=\"Training Dummies\", size=56, color={0,0.8,1}, optKey=\"pin_Dummies\" , labelAnchor=\"BOTTOM\", labelOffsetX=0, labelOffsetY=-8 },\n    -- Upgrade\n    { x=0.48434146245321, y=0.62011649780273, text=\"Upgrade\", size=60, color={1,0,0}, optKey=\"pin_Upgrade\" , labelAnchor=\"RIGHT\", labelOffsetX=8, labelOffsetY=0 },\n    -- Transmog\n    { x=0.52620109100342, y=0.57963483581543, text=\"Transmog\", size=60, color={0,0.8,1}, optKey=\"pin_Transmog\" , labelAnchor=\"BOTTOM\", labelOffsetX=0, labelOffsetY=-4 },\n  }\n\n  return pins\nend\n\nlocal OPT_KEYS = {\n  \"pin_AH\",\"pin_TradingPost\",\"pin_CraftOrders\",\"pin_Inn\",\"pin_Portal1\",\"pin_Portal2\",\"pin_Dummies\",\"pin_PetVendor\",\"pin_Upgrade\",\"pin_Transmog\",\"pin_Crafting\",\"pin_Catalyst\",\n}\n\nlocal function BuildOptHash()\n  local h = \"\"\n  for i = 1, #OPT_KEYS do\n    local k = OPT_KEYS[i]\n    h = h .. \"||\" .. k .. \"=\" .. tostring(Enabled(k))\n  end\n  return h\nend\n\nlocal function RebuildPins(overlay)\n  ClearPins()\n  if not overlay then return end\n\n  local cw, ch = overlay:GetWidth(), overlay:GetHeight()\n  if not (cw and ch and cw > 0 and ch > 0) then return end\n\n  local fontPath = (GameFontNormal and GameFontNormal.GetFont and GameFontNormal:GetFont()) or \"Fonts\\\\FRIZQT__.TTF\"\n  local pins = GetPins()\n\n  for _, d in ipairs(pins) do\n    if d.text and d.text ~= \"\" then\n      if (not d.optKey) or Enabled(d.optKey) then\n        local pin = AcquirePin(overlay)\n\n        -- Dot color: use pin color, slightly brightened for visibility\n        local c = d.color or {1, 1, 1}\n        pin.dot:SetVertexColor(c[1] or 1, c[2] or 1, c[3] or 1, 1)\n\n        -- Label\n        local size = tonumber(d.size) or 40\n        pin.text:SetFont(fontPath, size, \"OUTLINE\")\n        pin.text:SetText(d.text)\n        pin.text:SetTextColor(c[1] or 1, c[2] or 1, c[3] or 1, 1)\n\n        if ApplyLabelAnchor then ApplyLabelAnchor(pin, d) end\n        -- Frame anchors:\n        -- Position the frame's CENTER at the exact map coordinate, then dot sits at CENTER.\n        pin:ClearAllPoints()\n        pin:SetPoint(\"CENTER\", overlay, \"TOPLEFT\", (d.x or 0.5) * cw, -(d.y or 0.5) * ch)\n\n        -- Give the frame enough size to contain dot + text (avoid clipping).\n        local tw = pin.text:GetStringWidth() or 0\n        local th = pin.text:GetStringHeight() or 0\n        pin:SetSize(6 + 8 + tw + 6, max(6, th) + 6)\n\n        pin:Show()\n      end\n    end\n  end\nend\n\nlocal function Update(force)\n  local overlay = EnsureOverlay()\n  if not overlay then return end\n\n  if not ShouldShow() then\n    overlay:Hide()\n    ClearPins()\n    st.lastMapID, st.lastW, st.lastH, st.lastOptHash = nil, nil, nil, nil\n    return\n  end\n\n  overlay:Show()\n\n  -- Keep alpha synced even when we don't rebuild pins\n  if overlay.SetAlpha then overlay:SetAlpha(GetDesiredAlpha()) end\n\n  local cw, ch = overlay:GetWidth(), overlay:GetHeight()\n  local mapID = WorldMapFrame:GetMapID()\n  local optHash = BuildOptHash()\n\n  if force\n    or st.lastMapID ~= mapID\n    or st.lastW ~= cw\n    or st.lastH ~= ch\n    or st.lastOptHash ~= optHash\n  then\n    st.lastMapID, st.lastW, st.lastH, st.lastOptHash = mapID, cw, ch, optHash\n    RebuildPins(overlay)\n  end\nend\n\n\nlocal function ScheduleUpdate(force)\n  if st._pendingUpdate then return end\n  st._pendingUpdate = true\n  C_Timer.After(0, function()\n    st._pendingUpdate = false\n    Update(force)\n  end)\nend\n\n\nlocal function HookOnce()\n  if st.hooked then return end\n  st.hooked = true\n  if not WorldMapFrame then return end\n\n  WorldMapFrame:HookScript(\"OnShow\", function()\n    st.lastMapID = nil\n    st.lastW, st.lastH = nil, nil\n    st.lastOptHash = nil\n    ScheduleUpdate(true)\n  end)\n  WorldMapFrame:HookScript(\"OnHide\", function()\n    if st.overlay then st.overlay:Hide() end\n    ClearPins()\n  end)\n\n\n  if WorldMapFrame.ScrollContainer then\n    -- Fix 1-frame misalignment during pan/zoom by updating on next frame\n    WorldMapFrame.ScrollContainer:HookScript(\"OnMouseWheel\", function() ScheduleUpdate(false) end)\n    -- Pan finished replacement: ScrollFrame does not support \"OnPanFinished\" on all clients.\n    -- Use OnMouseUp (after dragging/panning) to refresh on next frame.\n    WorldMapFrame.ScrollContainer:HookScript(\"OnMouseUp\", function() ScheduleUpdate(false) end)\n\n    -- Optional: some clients may have OnPanFinished; hook it only if supported (no errors)\n    pcall(WorldMapFrame.ScrollContainer.HookScript, WorldMapFrame.ScrollContainer, \"OnPanFinished\", function() ScheduleUpdate(false) end)\n  end\n\n  hooksecurefunc(WorldMapFrame, \"SetMapID\", function() ScheduleUpdate(true) end)\n\n  local canvas = GetCanvas()\n  if canvas and canvas.HookScript then\n    canvas:HookScript(\"OnSizeChanged\", function() ScheduleUpdate(true) end)\n  end\nend\n\nHookOnce()\n\n-- Force rebuild when the CustomLua is (re)executed (e.g. after Apply), no /reload needed.\nif st then\n  st.lastMapID = nil\n  st.lastW, st.lastH = nil, nil\n  st.lastOptHash = nil\nend\nUpdate(true)",
