["luaCode"] = "-- Silvermoon (Midnight) Map Overlay for World Map\n-- Shows only when the map is open and the current UiMapID is 2393.\n\nlocal TARGET_MAP_ID = 2393\n\nlocal PINS = {\n  { x=0.54069096247355, y=0.74944536685944, text=\"Auction House\", size=60, color={ 1.000, 1.000, 1.000 }, shape=\"DOT\" },\n  { x=0.49374532699585, y=0.81281783580780, text=\"Trading Post\", size=60, color={ 0.000, 1.000, 0.000 }, shape=\"DOT\" },\n  { x=0.56960840225220, y=0.78788504600525, text=\"Delve Vendor\", size=60, color={ 0.000, 1.000, 0.000 }, shape=\"DOT\" },\n  { x=0.60963875452677, y=0.70338006019592, text=\"Inn & Cooking\", size=60, color={ 1.000, 0.500, 0.000 }, shape=\"DOT\" },\n  { x=0.38163582483927, y=0.78515071868896, text=\"Barber Shop\", size=60, color={ 0.000, 1.000, 0.000 }, shape=\"DOT\" },\n  { x=0.49206949869792, y=0.55926136970520, text=\"Crafting Orders\", size=60, color={ 1.000, 0.000, 0.000 }, shape=\"DOT\" },\n  { x=0.78680613835653, y=0.75295894145966, text=\"(Enchanting, Leatherworking, Tailoring, Herbalism)\", size=50, color={ 0.000, 0.800, 1.000 }, shape=\"DOT\" },\n  { x=0.70827452341715, y=0.86154980659485, text=\"(Skinning, Jewelcrafting, Mining, Blacksmithing, Engineering)\", size=50, color={ 0.000, 0.800, 1.000 }, shape=\"DOT\" },\n  { x=0.69307126998901, y=0.79836215972900, text=\"Tier Conversion\", size=60, color={ 0.000, 0.800, 1.000 }, shape=\"DOT\" },\n  { x=0.37147251764933, y=0.58234677314758, text=\"Timeways\", size=70, color={ 1.000, 1.000, 0.000 }, shape=\"DOT\" },\n  { x=0.74290952682495, y=0.60173225402832, text=\"Bank\", size=60, color={ 1.000, 0.000, 0.000 }, shape=\"DOT\" },\n  { x=0.66967598597209, y=0.59370460510254, text=\"Inn\", size=60, color={ 1.000, 0.500, 0.000 }, shape=\"DOT\" },\n  { x=0.52584145863851, y=0.62129983901978, text=\"Portal\", size=60, color={ 0.000, 0.800, 1.000 }, shape=\"DOT\" },\n  { x=0.30991748174032, y=0.80372273921967, text=\"PvP\", size=60, color={ 0.000, 0.800, 1.000 }, shape=\"DOT\" },\n  { x=0.36068925857544, y=0.86993203163147, text=\"Training Dummies\", size=56, color={ 0.000, 0.800, 1.000 }, shape=\"DOT\" },\n  { x=0.46885196367900, y=0.51557934284210, text=\"(Jewelcrafting, Skinning, Engineering, Mining, Blacksmithing)\", size=50, color={ 0.000, 0.800, 1.000 }, shape=\"DOT\" },\n  { x=0.56698865890503, y=0.51368012428284, text=\"(Inscription, Alchemy, Herbalism, Enchanting, Tailoring, Leatherworking)\", size=50, color={ 0.000, 0.800, 1.000 }, shape=\"DOT\" },\n  { x=0.50563634236654, y=0.68484845161438, text=\"Bank\", size=60, color={ 1.000, 0.000, 0.000 }, shape=\"DOT\" },\n  { x=0.35699478785197, y=0.75478868484497, text=\"Pet Vendor\", size=60, color={ 0.000, 1.000, 0.000 }, shape=\"DOT\" },\n  { x=0.44692592620850, y=0.62579312324524, text=\"Fishing\", size=60, color={ 1.000, 1.000, 1.000 }, shape=\"DOT\" },\n  { x=0.48434146245321, y=0.64081649780273, text=\"Upgrade\", size=60, color={ 1.000, 0.000, 0.000 }, shape=\"DOT\" },\n  { x=0.77319266001383, y=0.72507128715515, text=\"( )\", size=70, color={ 0.000, 0.800, 1.000 }, shape=\"DOT\" }, -- optional placeholder from source; can delete\n  { x=0.38531108856201, y=0.72573223114014, text=\"Portal\", size=60, color={ 0.000, 0.800, 1.000 }, shape=\"DOT\" },\n  { x=0.38600109100342, y=0.68453483581543, text=\"Transmog\", size=60, color={ 0.000, 0.800, 1.000 }, shape=\"DOT\" },\n}\n\nlocal function GetCanvas()\n  if WorldMapFrame and WorldMapFrame.GetCanvas then\n    return WorldMapFrame:GetCanvas()\n  end\n  if WorldMapFrame and WorldMapFrame.ScrollContainer and WorldMapFrame.ScrollContainer.Child then\n    return WorldMapFrame.ScrollContainer.Child\n  end\n  return nil\nend\n\nlocal function GlyphForShape(shape)\n  if shape == \"UP\" then return \"▲\" end\n  if shape == \"DOWN\" then return \"▼\" end\n  if shape == \"LEFT\" then return \"◀\" end\n  if shape == \"RIGHT\" then return \"▶\" end\n  return \"●\"\nend\n\nlocal function ClearPins()\n  if not aura_env.activePins then return end\n  for i = 1, #aura_env.activePins do\n    local p = aura_env.activePins[i]\n    if p then\n      p:Hide()\n      p:SetParent(nil)\n      aura_env.pinPool[#aura_env.pinPool + 1] = p\n    end\n  end\n  wipe(aura_env.activePins)\nend\n\nlocal function AcquirePin(parent)\n  aura_env.pinPool = aura_env.pinPool or {}\n  aura_env.activePins = aura_env.activePins or {}\n\n  local p = tremove(aura_env.pinPool)\n  if not p then\n    p = CreateFrame(\"Frame\", nil, parent)\n    p.text = p:CreateFontString(nil, \"OVERLAY\", \"GameFontNormal\")\n    p.text:SetJustifyH(\"CENTER\")\n    p.text:SetPoint(\"CENTER\", p, \"CENTER\", 0, 0)\n  end\n\n  p:SetParent(parent)\n  aura_env.activePins[#aura_env.activePins + 1] = p\n  return p\nend\n\nlocal function EnsureOverlay()\n  local canvas = GetCanvas()\n  if not canvas then return nil end\n\n  if not aura_env.overlay or aura_env.overlay:GetParent() ~= canvas then\n    if aura_env.overlay then\n      aura_env.overlay:SetParent(canvas)\n      aura_env.overlay:ClearAllPoints()\n    else\n      aura_env.overlay = CreateFrame(\"Frame\", nil, canvas)\n    end\n    aura_env.overlay:SetAllPoints(canvas)\n    aura_env.overlay:SetFrameStrata(\"MEDIUM\")\n    aura_env.overlay:SetFrameLevel(500)\n  end\n\n  return aura_env.overlay\nend\n\nlocal function RebuildPins(overlay)\n  if not overlay then return end\n  ClearPins()\n\n  local cw, ch = overlay:GetWidth(), overlay:GetHeight()\n  if not (cw and ch and cw > 0 and ch > 0) then return end\n\n  local fontPath = (GameFontNormal and GameFontNormal.GetFont and GameFontNormal:GetFont()) or \"Fonts\\\\FRIZQT__.TTF\"\n\n  for _, d in ipairs(PINS) do\n    local text = (d.text and d.text ~= \"\" and d.text ~= \"( )\") and d.text or GlyphForShape(d.shape)\n    local pin = AcquirePin(overlay)\n\n    local size = tonumber(d.size) or 40\n    pin.text:SetFont(fontPath, size, \"OUTLINE\")\n    pin.text:SetText(text)\n\n    local c = d.color or {1, 1, 1}\n    pin.text:SetTextColor(c[1] or 1, c[2] or 1, c[3] or 1)\n\n    pin:SetSize(pin.text:GetStringWidth() + 6, pin.text:GetStringHeight() + 6)\n    pin:ClearAllPoints()\n    pin:SetPoint(\"CENTER\", overlay, \"TOPLEFT\", (d.x or 0.5) * cw, -(d.y or 0.5) * ch)\n    pin:Show()\n  end\nend\n\nlocal function ShouldShow()\n  if not (WorldMapFrame and WorldMapFrame.IsShown and WorldMapFrame:IsShown()) then return false end\n  if not (WorldMapFrame.GetMapID) then return false end\n  return (WorldMapFrame:GetMapID() == TARGET_MAP_ID)\nend\n\nlocal function Update()\n  if not ShouldShow() then\n    if aura_env.overlay then aura_env.overlay:Hide() end\n    return\n  end\n\n  local overlay = EnsureOverlay()\n  if not overlay then return end\n  overlay:Show()\n\n  local cw, ch = overlay:GetWidth(), overlay:GetHeight()\n  local mapID = WorldMapFrame:GetMapID()\n\n  if aura_env._builtMapID ~= mapID or aura_env._builtW ~= cw or aura_env._builtH ~= ch then\n    aura_env._builtMapID, aura_env._builtW, aura_env._builtH = mapID, cw, ch\n    RebuildPins(overlay)\n  end\nend\n\n-- one-time OnUpdate ticker (keeps it stable when zooming, resizing, or switching maps)\nif not aura_env._overlayTickerInit then\n  aura_env._overlayTickerInit = true\n  aura_env._acc = 0\n  local overlay = EnsureOverlay()\n  if overlay then\n    overlay:SetScript(\"OnUpdate\", function(self, elapsed)\n      aura_env._acc = (aura_env._acc or 0) + (elapsed or 0)\n      if aura_env._acc < 0.10 then return end\n      aura_env._acc = 0\n      Update()\n    end)\n  end\nend\n\nUpdate()",
